* {
    padding: 0px;
    margin: 0px;
    box-sizing: border-box;
    transition: transform .4s linear !important;
}

body {
    --colorContent: #ec2227;
}

/* Nav-link */
.nav-link {
    padding: 0;
}

.nav-link #changeLang {
    position: fixed;
    z-index: 1000;
    right: clamp(20px, 3vw, 50px);
    bottom: 5vh;
    background-color: transparent;
    border: transparent;
    padding: clamp(24px, 5vw, 45px);
    background-size: cover;
    background-image: var(--bg-lang);
}

.nav-link #changePage {
    position: fixed;
    padding: clamp(12px, 2.5vw, 25px);
    line-height: clamp(20px, 1.6vw, 25px);
    color: #39386a;
    background-color: var(--colorContent);
    bottom: 5vh;
    left: clamp(20px, 3vw, 50px);
    z-index: 1000;
    border-radius: 100%;
    border: transparent;
    font-size: clamp(26px, 3.5vw, 40px);
    font-weight: 600;
}

.nav-link a {
    position: fixed;
    left: clamp(20px, 3vw, 50px);
    padding: clamp(12px, 2.5vw, 25px);
    line-height: clamp(20px, 1.6vw, 25px);
    z-index: 1000;
    border-radius: 100%;
    visibility: visible;
    background-color: var(--colorContent);
    color: #39386a;
    font-size: clamp(26px, 3.5vw, 40px);
    font-weight: 600;
}

.nav-link .active {
    background-color: yellowgreen;
}

.nav-link a:nth-of-type(1) {
    bottom: 11vh;
}

.nav-link a:nth-of-type(2) {
    bottom: 17vh;
}

.nav-link a:nth-of-type(3) {
    bottom: 23vh;
}

.nav-link a:nth-of-type(4) {
    bottom: 29vh;
}

.nav-link a:nth-of-type(5) {
    bottom: 35vh;
}

.nav-link a:nth-of-type(6) {
    bottom: 41vh;
}

.hidden {
    visibility: hidden !important;
}

.nav-link .active {
    background-color: rgb(34, 150, 228);
    color: black;
}

.nav-link a span {
    position: fixed;
    padding-left: clamp(20px, 4vw, 55px);
    line-height: clamp(26px, 2.5vw, 37px);
    z-index: 1000;
    visibility: visible;
    color: orangered;
    font-weight: 700;
    font-size: clamp(24px, 3vw, 36px);
}

.nav-link .active span {
    color: rgb(34, 150, 228);
}


