/* Nội dung dọc */
.bg-content {
    background: fixed;
    background-image: var(--bg-img);
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
}

.overlay {
    background: rgba(32, 32, 32, 0.65);
    width: 100%;
    height: 100vh;
    position: fixed;
    top: 0;
    left: 0;
    z-index: 1;
}

#trangchu {
    height: 100vh;
}

#congnghiep {
    height: 100vh;
}

.logo {
    width: 30%;
    margin: auto;
    padding-top: 2vh;
    position: relative;
    z-index: 2;
}

.logo img {
    width: 100%;
    display: block;
    margin: auto;
}

.content {
    position: relative;
    z-index: 20;
}

.content-box {
    width: 80%;
    margin: auto;
    padding-top: clamp(38px, 8vw, 130px);
}

.box-first {
    padding-top: 20px !important;
}



.content h1 {
    text-align: center;
    color: var(--colorContent);
    font-weight: 700;
    width: 80%;
    margin: auto;
    font-size: clamp(36px, 6vw, 86px);
}

.content p {
    width: 100%;
    text-align: justify;
    padding: clamp(12px, 2vw, 20px) clamp(20px, 4vw, 50px) 0;
    margin: 0 auto;
    color: white;
    font-size: clamp(8px, 2.5vw, 30px);
}

.content-box p {
    text-align: center;
    text-align-last: center;
    padding: clamp(10px, 2vw, 20px) 0 0;
}

.content p span {
    display: inline-block;
    text-align-last: left;
}

.content h2 {
    text-align: center;
    color: var(--colorContent);
    margin: clamp(12px, 3vw, 25px);
    font-size: clamp(26px, 5vw, 68px);
}

.content img {
    width: 100%;
}

.portlofio {
    margin-top: 7%;
}

.portlofio a {
    text-decoration: none;
    color: #000;
}

.frame {
    width: 80%;
    margin: auto;
}

.portlofio-content {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: clamp(10px, 3vw, 35px);
}

.portlofio-box {
    border-radius: clamp(6px, 1vw, 10px);
    background-color: #629cf1a1;
    position: relative;
    padding: clamp(12px, 5vw, 50px);
    line-height: clamp(22px, 4vw, 50px);
    text-align: center;
    font-size: clamp(6px, 1.6vw, 18px);
    font-weight: 700;
}

.portlofio-box:first-of-type {
    grid-column: 1/ 3;
}

.portlofio-box:nth-child(2) {
    grid-column: 3/ 4;
}

.portlofio-box:nth-child(3) {
    grid-column: 1;
}

.portlofio-box:nth-child(4) {
    grid-column: 2/4;
}

.portlofio-box:nth-child(5) {
    grid-column: 1/ 3;
}

.portlofio-box:nth-child(6) {
    grid-column: 3/ 4;
}

