.back-button {
    position: fixed;
    left: clamp(20px, 3vw, 50px);
    padding: clamp(12px, 2.5vw, 25px);
    line-height: clamp(20px, 1.6vw, 25px);
    color: #39386a;
    background-color: var(--colorContent);
    bottom: 5vh;
    z-index: 1000;
    border-radius: 100%;
    border: transparent;
    font-size: clamp(26px, 3.5vw, 40px);
    font-weight: 600;
}

@media (orientation: portrait) {
    .screen-landscape {
        display: none !important;
    }

    .span-landscape {
        display: inline !important;
    }
}

@media (orientation: landscape) {
    .nav-link a:nth-of-type(1) {
        bottom: 15vh;
        left: 50px;
    }

    .nav-link a:nth-of-type(2) {
        bottom: 26vh;
        left: 50px;
    }

    .nav-link a:nth-of-type(3) {
        bottom: 37vh;
        left: 50px;
    }

    .nav-link a:nth-of-type(4) {
        bottom: 48vh;
        left: 50px;
    }

    .nav-link a:nth-of-type(5) {
        bottom: 59vh;
        left: 50px;
    }

    .nav-link a:nth-of-type(6) {
        bottom: 70vh;
        left: 50px;
    }
}